Here is the complete function using Dijkstra's algorithm. To resolve ties correctly by lexicographical path order, the priority queue stores the tuple `(cost, path)` so that ties in path cost naturally break by the smallest path list.

```python
import heapq

def shortest_path(graph, src, dst):
    if src == dst:
        return [src] if src in graph or any(src in neighbors for neighbors in graph.values()) else []

    # Priority queue stores tuples of (cumulative_cost, path)
    # Python tuples are compared element-wise, breaking ties by path lexicographically.
    pq = [(0, [src])]
    best_cost = {}

    while pq:
        cost, path = heapq.heappop(pq)
        u = path[-1]

        if u == dst:
            return path

        # If we have already visited u with a strictly better cost, skip
        if u in best_cost and best_cost[u] < cost:
            continue
        best_cost[u] = cost

        for v, weight in graph.get(u, {}).items():
            new_cost = cost + weight
            if v not in best_cost or new_cost <= best_cost[v]:
                heapq.heappush(pq, (new_cost, path + [v]))

    return []
